'use client';
import { useState, useEffect } from 'react';
import { copyToClipboard } from '@/lib/utils/clipboard';

export default function GrowthCopilotPage() {
    const [doubtText, setDoubtText] = useState('');
    const [imagePreview, setImagePreview] = useState(null);
    const [imageBase64, setImageBase64] = useState(null);
    const [platform, setPlatform] = useState('facebook');
    const [isGenerating, setIsGenerating] = useState(false);
    const [results, setResults] = useState(null);
    const [copiedIndex, setCopiedIndex] = useState(null);

    // Setup Paste Event Listener (So founder can just hit Cmd+V)
    useEffect(() => {
        const handlePaste = (e) => {
            if (e.clipboardData.files.length > 0) {
                const file = e.clipboardData.files[0];
                if (file.type.startsWith('image/')) {
                    handleImageUpload(file);
                }
            }
        };
        window.addEventListener('paste', handlePaste);
        return () => window.removeEventListener('paste', handlePaste);
    }, []);

    const handleImageUpload = (file) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result;
            setImagePreview(base64String);
            // Split off the header (e.g. "data:image/png;base64,")
            const pureBase64 = base64String.split(',')[1];
            setImageBase64(pureBase64);
        };
        reader.readAsDataURL(file);
    };

    const handleGenerate = async () => {
        if (!doubtText && !imageBase64) return alert('Provide text or an image doubt');
        setIsGenerating(true);
        setResults(null);
        setCopiedIndex(null);

        try {
            const res = await fetch('/api/admin/growth/solve', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ 
                    textContent: doubtText, 
                    imageBase64: imageBase64 
                })
            });

            if (res.ok) {
                const json = await res.json();
                setResults(json);
            } else {
                alert('Generation Failed');
            }
        } catch (e) {
            console.error(e);
            alert('Generation Exception');
        }
        setIsGenerating(false);
    };

    const handleCopy = async (variantName, text) => {
        await copyToClipboard(text);
        setCopiedIndex(variantName);

        // Silent MD Tracker: Memory Hook
        fetch('/api/admin/growth/log', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                platform,
                topicDetected: results?.topic_detected,
                originalDoubtText: doubtText || 'Image Based',
                selectedVariantText: text
            })
        }).catch(err => console.error("Failed to commit to Memory Tracker", err));
    };

    return (
        <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '40px 20px', minHeight: '100vh', background: 'var(--bg-primary)' }}>
            <div className="flex items-center gap-3 mb-8">
                <span className="text-4xl">🚀</span>
                <div>
                    <h1 className="text-3xl font-black mb-1">Growth Copilot</h1>
                    <p className="text-muted">Human-in-the-Loop Organic Customer Acquisition</p>
                </div>
            </div>

            <div className="grid grid-2 gap-8 items-start">

                {/* INTERFACE LAYER */}
                <div className="card" style={{ padding: '32px' }}>
                    <h3 className="text-xl font-bold mb-4">1. Ingest Doubt</h3>
                    <p className="text-sm text-muted mb-6">Take a screenshot of a Facebook/Telegram doubt and press <strong className="text-white bg-slate-800 px-2 py-1 rounded">Cmd + V</strong> to paste it.</p>

                    <div 
                        style={{ border: '2px dashed var(--border-color)', borderRadius: '12px', minHeight: '150px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '24px', background: imagePreview ? 'transparent' : 'rgba(255,255,255,0.02)', position: 'relative', overflow: 'hidden' }}
                    >
                        {imagePreview ? (
                            <img src={imagePreview} style={{ width: '100%', height: '100%', objectFit: 'contain', maxHeight: '300px' }} alt="Pasted Doubt" />
                        ) : (
                            <span className="text-muted font-bold text-sm">Paste Image Here</span>
                        )}
                        {imagePreview && (
                            <button onClick={() => {setImagePreview(null); setImageBase64(null)}} style={{ position: 'absolute', top: 12, right: 12, background: 'rgba(0,0,0,0.8)', padding: '4px 10px', borderRadius: '4px', fontSize: '12px' }}>Clear</button>
                        )}
                    </div>

                    <div className="mb-6">
                        <label className="block text-sm font-bold text-gray-400 mb-2">Or Paste Text</label>
                        <textarea 
                            value={doubtText}
                            onChange={(e) => setDoubtText(e.target.value)}
                            placeholder="E.g. I don't understand how Newton's 3rd Law applies to the tension puzzle..."
                            className="input"
                            style={{ minHeight: '100px' }}
                        />
                    </div>

                    <div className="flex justify-between items-center mt-6 py-4 border-t border-gray-800">
                        <div className="flex items-center gap-3">
                            <span className="text-sm font-bold text-gray-400">Target</span>
                            <select className="input" value={platform} onChange={(e) => setPlatform(e.target.value)} style={{ padding: '6px 12px', height: 'auto' }}>
                                <option value="facebook">Facebook</option>
                                <option value="telegram">Telegram</option>
                                <option value="reddit">Reddit</option>
                            </select>
                        </div>
                        <button 
                            onClick={handleGenerate} 
                            disabled={isGenerating}
                            className="btn btn-primary"
                        >
                            {isGenerating ? 'Firing Vision Engine...' : '⚡ Generate Variants'}
                        </button>
                    </div>
                </div>

                {/* OUTPUT LAYER */}
                <div>
                    {!results && !isGenerating ? (
                        <div style={{ padding: '60px', textAlign: 'center', border: '1px solid var(--border-color)', borderRadius: '16px', background: 'rgba(0,0,0,0.2)' }}>
                            <span className="text-5xl opacity-50 block mb-4">🧠</span>
                            <h3 className="text-xl text-gray-400">Awaiting Target Data</h3>
                        </div>
                    ) : isGenerating ? (
                        <div style={{ padding: '60px', textAlign: 'center', border: '1px solid var(--border-color)', borderRadius: '16px', background: 'rgba(0,0,0,0.2)' }}>
                            <div className="spinner mb-4 mx-auto" />
                            <h3 className="text-xl text-gray-400 animate-pulse">Running AI Copilot...</h3>
                        </div>
                    ) : (
                        <div className="animate-fade-in-up">
                            <div className="mb-4">
                                <span className="px-3 py-1 bg-green-900 text-green-400 rounded-full text-xs font-bold mr-2">Target Acquired</span>
                                <span className="text-gray-400 text-sm">Detected Topic: </span>
                                <strong className="text-white">{results.topic_detected}</strong>
                            </div>

                            <div className="flex flex-col gap-4">
                                {/* Variant 1 */}
                                <div className="card" style={{ borderLeft: '4px solid #3b82f6' }}>
                                    <div className="flex justify-between items-center mb-3">
                                        <h4 className="font-bold text-blue-400">1. Concise Variant</h4>
                                        <button onClick={() => handleCopy('concise', results.concise)} className="text-xs bg-blue-900 text-white px-3 py-1 rounded">
                                            {copiedIndex === 'concise' ? '✓ Copied' : 'Copy Text'}
                                        </button>
                                    </div>
                                    <p className="text-sm leading-relaxed whitespace-pre-wrap">{results.concise}</p>
                                </div>

                                {/* Variant 2 */}
                                <div className="card" style={{ borderLeft: '4px solid #10b981' }}>
                                    <div className="flex justify-between items-center mb-3">
                                        <h4 className="font-bold text-emerald-400">2. Detailed Breakdown</h4>
                                        <button onClick={() => handleCopy('detailed', results.detailed)} className="text-xs bg-emerald-900 text-white px-3 py-1 rounded">
                                            {copiedIndex === 'detailed' ? '✓ Copied' : 'Copy Text'}
                                        </button>
                                    </div>
                                    <p className="text-sm leading-relaxed whitespace-pre-wrap">{results.detailed}</p>
                                </div>

                                {/* Variant 3 */}
                                <div className="card" style={{ borderLeft: '4px solid #f59e0b' }}>
                                    <div className="flex justify-between items-center mb-3">
                                        <h4 className="font-bold text-amber-400">3. Highly Conversational</h4>
                                        <button onClick={() => handleCopy('conversational', results.conversational)} className="text-xs bg-amber-900 text-white px-3 py-1 rounded">
                                            {copiedIndex === 'conversational' ? '✓ Copied' : 'Copy Text'}
                                        </button>
                                    </div>
                                    <p className="text-sm leading-relaxed whitespace-pre-wrap">{results.conversational}</p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useState, useEffect } from 'react';

export default function AdminLayout({ children }) {
    const pathname = usePathname();
    const router = useRouter();
    const [authState, setAuthState] = useState('loading'); // 'loading' | 'authorized' | 'denied'

    useEffect(() => {
        async function checkAdmin() {
            try {
                const res = await fetch('/api/auth/me');
                if (res.ok) {
                    const data = await res.json();
                    if (data.user?.role === 'admin') {
                        setAuthState('authorized');
                    } else {
                        setAuthState('denied');
                    }
                } else {
                    setAuthState('denied');
                }
            } catch {
                setAuthState('denied');
            }
        }
        checkAdmin();
    }, []);

    if (authState === 'loading') {
        return (
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: '#050510' }}>
                <div style={{ width: 40, height: 40, border: '2px solid #6366f1', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite' }}></div>
                <style jsx>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
            </div>
        );
    }

    if (authState === 'denied') {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: '#050510', color: 'white', gap: 16 }}>
                <div style={{ fontSize: '4rem' }}>🔒</div>
                <h1 style={{ fontSize: '1.5rem', fontWeight: 800, color: '#ef4444' }}>Access Denied</h1>
                <p style={{ color: '#64748b', maxWidth: 400, textAlign: 'center' }}>
                    You don't have permission to access the Admin Portal. This area is restricted to administrators only.
                </p>
                <button onClick={() => window.location.href = '/dashboard'} style={{
                    marginTop: 16, padding: '12px 32px', borderRadius: 12, border: '1px solid rgba(99,102,241,0.3)',
                    background: 'rgba(99,102,241,0.1)', color: '#a5b4fc', fontWeight: 600, cursor: 'pointer',
                    fontSize: '0.9rem', transition: 'all 0.2s'
                }}>
                    ← Back to Dashboard
                </button>
            </div>
        );
    }

    const navItems = [
        { name: 'Overview', path: '/admin', icon: '📊' },
        { name: 'Runtime Dashboard', path: '/admin/runtime', icon: '🖥️' },
        { name: 'Integrity', path: '/admin/integrity', icon: '🛡️' },
        { name: 'Ops Control Room', path: '/admin/ops', icon: '🧯' },
        { name: 'Question Bank', path: '/admin/questions', icon: '📝' },
        { name: 'NCERT Library', path: '/admin/ncert', icon: '📚' },
        { name: 'User Management', path: '/admin/users', icon: '👥' },
        { name: 'Revenue', path: '/admin/revenue', icon: '💰' },
    ];

    const bottomItems = [
        { name: 'Back to App', path: '/dashboard', icon: '⬅️' },
    ];

    return (
        <div style={{ display: 'flex', minHeight: '100vh', background: '#050510', color: 'white' }}>
            {/* Ambient Background Glow */}
            <div style={{ position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 0 }}>
                <div style={{ position: 'absolute', top: 0, left: 0, width: 500, height: 500, background: 'rgba(99,102,241,0.04)', borderRadius: '50%', filter: 'blur(120px)' }}></div>
                <div style={{ position: 'absolute', bottom: 0, right: 0, width: 500, height: 500, background: 'rgba(139,92,246,0.04)', borderRadius: '50%', filter: 'blur(120px)' }}></div>
            </div>

            {/* Glass Sidebar */}
            <aside style={{
                width: 280, background: 'rgba(255,255,255,0.03)', backdropFilter: 'blur(20px)',
                borderRight: '1px solid rgba(255,255,255,0.08)', display: 'flex', flexDirection: 'column',
                zIndex: 20, position: 'relative'
            }}>
                <div style={{ padding: '28px 24px', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                    <h1 style={{
                        fontSize: '1.3rem', fontWeight: 800,
                        background: 'linear-gradient(135deg, #6366f1, #a78bfa)',
                        WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent'
                    }}>
                        Admin Portal
                    </h1>
                    <p style={{ fontSize: '0.65rem', color: '#475569', marginTop: 4, textTransform: 'uppercase', letterSpacing: '0.15em' }}>Command Center</p>
                </div>

                <nav style={{ flex: 1, padding: '12px 12px' }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                        {navItems.map(item => {
                            const isActive = pathname === item.path || (item.path !== '/admin' && pathname.startsWith(item.path));
                            return (
                                <a key={item.path} href={item.path} style={{
                                    display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px',
                                    borderRadius: 12, textDecoration: 'none', transition: 'all 0.2s',
                                    fontSize: '0.9rem', fontWeight: 500,
                                    background: isActive ? 'rgba(99,102,241,0.1)' : 'transparent',
                                    color: isActive ? '#a5b4fc' : '#64748b',
                                    border: isActive ? '1px solid rgba(99,102,241,0.2)' : '1px solid transparent',
                                    boxShadow: isActive ? '0 0 20px rgba(99,102,241,0.1)' : 'none'
                                }}>
                                    <span style={{ fontSize: '1.1rem' }}>{item.icon}</span>
                                    <span>{item.name}</span>
                                    {isActive && (
                                        <div style={{ marginLeft: 'auto', width: 6, height: 6, borderRadius: '50%', background: '#6366f1', boxShadow: '0 0 10px #6366f1' }}></div>
                                    )}
                                </a>
                            );
                        })}
                    </div>
                </nav>

                <div style={{ padding: '12px 12px', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                    {bottomItems.map(item => (
                        <a key={item.path} href={item.path} style={{
                            display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px',
                            borderRadius: 12, textDecoration: 'none', color: '#64748b',
                            fontSize: '0.9rem', fontWeight: 500, transition: 'all 0.15s'
                        }}>
                            <span style={{ fontSize: '1.1rem' }}>{item.icon}</span>
                            <span>{item.name}</span>
                        </a>
                    ))}
                </div>

                <div style={{ padding: '16px 20px', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                    <div style={{
                        background: 'linear-gradient(135deg, rgba(17,24,39,0.9), rgba(0,0,0,0.9))',
                        padding: 16, borderRadius: 14, border: '1px solid rgba(255,255,255,0.08)'
                    }}>
                        <p style={{ fontSize: '0.65rem', color: '#475569', marginBottom: 6, textTransform: 'uppercase', letterSpacing: '0.1em' }}>System Status</p>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                            <span style={{ width: 8, height: 8, background: '#22c55e', borderRadius: '50%', boxShadow: '0 0 8px rgba(34,197,94,0.5)' }}></span>
                            <span style={{ fontSize: '0.85rem', fontWeight: 600, color: '#4ade80' }}>Operational</span>
                        </div>
                    </div>
                </div>
            </aside>

            {/* Main Content Area */}
            <main style={{ flex: 1, overflow: 'auto', position: 'relative', zIndex: 10 }}>
                <div style={{ maxWidth: 1200, margin: '0 auto' }}>
                    {children}
                </div>
            </main>
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';

export default function AdminNCERTPage() {
    const [file, setFile] = useState(null);
    const [meta, setMeta] = useState({ subjectId: '', chapterId: '', title: '' });
    const [uploading, setUploading] = useState(false);
    const [books, setBooks] = useState([]);
    const [loadingBooks, setLoadingBooks] = useState(true);
    const [dragOver, setDragOver] = useState(false);

    useEffect(() => { fetchBooks(); }, []);

    const fetchBooks = async () => {
        setLoadingBooks(true);
        try {
            const res = await fetch('/api/admin/ncert/list');
            if (res.ok) {
                const data = await res.json();
                setBooks(data.books || []);
            }
        } catch (e) { /* API may not exist yet */ }
        setLoadingBooks(false);
    };

    const handleUpload = async (e) => {
        e.preventDefault();
        if (!file || !meta.subjectId || !meta.chapterId || !meta.title) {
            alert('Please fill all fields');
            return;
        }
        setUploading(true);
        const formData = new FormData();
        formData.append('file', file);
        formData.append('subjectId', meta.subjectId);
        formData.append('chapterId', meta.chapterId);
        formData.append('title', meta.title);
        try {
            const res = await fetch('/api/admin/ncert/upload', { method: 'POST', body: formData });
            const data = await res.json();
            if (res.ok) {
                setFile(null);
                setMeta({ subjectId: '', chapterId: '', title: '' });
                fetchBooks();
            } else {
                alert('Upload Failed: ' + data.error);
            }
        } catch (err) {
            console.error(err);
            alert('Upload Error');
        } finally { setUploading(false); }
    };

    const subjectMap = { '1': 'Physics', '2': 'Chemistry', '3': 'Biology' };
    const getSubjectColor = (id) => {
        switch (String(id)) {
            case '1': return { bg: 'rgba(59,130,246,0.12)', color: '#60a5fa', border: 'rgba(59,130,246,0.3)' };
            case '2': return { bg: 'rgba(16,185,129,0.12)', color: '#34d399', border: 'rgba(16,185,129,0.3)' };
            case '3': return { bg: 'rgba(249,115,22,0.12)', color: '#fb923c', border: 'rgba(249,115,22,0.3)' };
            default: return { bg: 'rgba(100,116,139,0.12)', color: '#94a3b8', border: 'rgba(100,116,139,0.3)' };
        }
    };

    return (
        <div style={{ padding: 32 }}>
            <header style={{ marginBottom: 32 }}>
                <h1 style={{ fontSize: '2rem', fontWeight: 800, background: 'linear-gradient(135deg, #6366f1, #a78bfa)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                    NCERT Library Manager
                </h1>
                <p style={{ color: '#64748b', marginTop: 8 }}>Upload and manage NCERT textbook PDFs for AI-powered learning.</p>
            </header>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: 24 }}>
                {/* Upload Card */}
                <div style={{
                    background: 'rgba(17,24,39,0.8)', border: '1px solid rgba(255,255,255,0.08)',
                    borderRadius: 16, padding: 24, backdropFilter: 'blur(20px)', alignSelf: 'start'
                }}>
                    <h3 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#f1f5f9', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span>📤</span> Upload New Textbook
                    </h3>
                    <form onSubmit={handleUpload} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', color: '#64748b', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 6 }}>Subject</label>
                                <select value={meta.subjectId} onChange={e => setMeta({ ...meta, subjectId: e.target.value })} style={{
                                    width: '100%', padding: '10px 14px', background: 'rgba(0,0,0,0.4)',
                                    border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10,
                                    color: '#f1f5f9', fontSize: '0.9rem', outline: 'none'
                                }}>
                                    <option value="">Select</option>
                                    <option value="1">Physics</option>
                                    <option value="2">Chemistry</option>
                                    <option value="3">Biology</option>
                                </select>
                            </div>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', color: '#64748b', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 6 }}>Chapter ID</label>
                                <input className="input" type="number" value={meta.chapterId} onChange={e => setMeta({ ...meta, chapterId: e.target.value })} placeholder="e.g. 101" style={{
                                    width: '100%', padding: '10px 14px', background: 'rgba(0,0,0,0.4)',
                                    border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10,
                                    color: '#f1f5f9', fontSize: '0.9rem', outline: 'none'
                                }} />
                            </div>
                        </div>

                        <div>
                            <label style={{ display: 'block', fontSize: '0.75rem', color: '#64748b', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 6 }}>Book / Chapter Title</label>
                            <input type="text" value={meta.title} onChange={e => setMeta({ ...meta, title: e.target.value })} placeholder="e.g. Electric Charges and Fields" style={{
                                width: '100%', padding: '10px 14px', background: 'rgba(0,0,0,0.4)',
                                border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10,
                                color: '#f1f5f9', fontSize: '0.9rem', outline: 'none'
                            }} />
                        </div>

                        {/* Drop Zone */}
                        <div
                            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
                            onDragLeave={() => setDragOver(false)}
                            onDrop={e => { e.preventDefault(); setDragOver(false); setFile(e.dataTransfer.files[0]); }}
                            style={{
                                padding: 32, border: `2px dashed ${dragOver ? '#6366f1' : 'rgba(255,255,255,0.1)'}`,
                                borderRadius: 14, textAlign: 'center', cursor: 'pointer',
                                background: dragOver ? 'rgba(99,102,241,0.05)' : 'transparent',
                                transition: 'all 0.2s'
                            }}>
                            <input type="file" accept="application/pdf" onChange={e => setFile(e.target.files[0])} style={{ display: 'none' }} id="ncert-upload" />
                            <label htmlFor="ncert-upload" style={{ cursor: 'pointer', display: 'block' }}>
                                <div style={{ fontSize: '2.5rem', marginBottom: 8 }}>📄</div>
                                {file ? (
                                    <span style={{ color: '#60a5fa', fontWeight: 600 }}>{file.name}</span>
                                ) : (
                                    <>
                                        <p style={{ color: '#94a3b8', fontWeight: 500 }}>Drop PDF here or click to browse</p>
                                        <p style={{ color: '#475569', fontSize: '0.75rem', marginTop: 4 }}>PDF files only, max 50MB</p>
                                    </>
                                )}
                            </label>
                        </div>

                        <button type="submit" disabled={uploading} className="btn btn-primary" style={{ width: '100%', padding: '14px', fontSize: '0.9rem' }}>
                            {uploading ? '⏳ Uploading...' : '📤 Upload PDF'}
                        </button>
                    </form>
                </div>

                {/* Library */}
                <div style={{
                    background: 'rgba(17,24,39,0.8)', border: '1px solid rgba(255,255,255,0.08)',
                    borderRadius: 16, padding: 24, backdropFilter: 'blur(20px)'
                }}>
                    <h3 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#f1f5f9', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span>📚</span> Uploaded Library
                        <span style={{ fontSize: '0.75rem', fontWeight: 600, color: '#64748b', marginLeft: 'auto' }}>{books.length} books</span>
                    </h3>

                    {loadingBooks ? (
                        <div style={{ display: 'flex', justifyContent: 'center', padding: 32 }}>
                            <div style={{ width: 28, height: 28, border: '2px solid #6366f1', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite' }}></div>
                        </div>
                    ) : books.length === 0 ? (
                        <div style={{ textAlign: 'center', padding: 40 }}>
                            <div style={{ fontSize: '3rem', marginBottom: 12 }}>📖</div>
                            <p style={{ color: '#475569', fontWeight: 500 }}>No books uploaded yet</p>
                            <p style={{ color: '#334155', fontSize: '0.8rem', marginTop: 4 }}>Upload your first NCERT PDF to get started</p>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                            {books.map((book, i) => {
                                const sc = getSubjectColor(book.subject_id);
                                return (
                                    <div key={i} style={{
                                        display: 'flex', alignItems: 'center', gap: 14, padding: '14px 16px',
                                        background: 'rgba(255,255,255,0.03)', borderRadius: 12,
                                        border: '1px solid rgba(255,255,255,0.04)',
                                        transition: 'all 0.15s'
                                    }}>
                                        <div style={{
                                            width: 40, height: 40, borderRadius: 10, display: 'flex',
                                            alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem',
                                            background: sc.bg, border: `1px solid ${sc.border}`, flexShrink: 0
                                        }}>📘</div>
                                        <div style={{ flex: 1, minWidth: 0 }}>
                                            <div style={{ fontWeight: 600, fontSize: '0.85rem', color: '#e2e8f0' }}>{book.title}</div>
                                            <div style={{ fontSize: '0.75rem', color: '#475569', marginTop: 2 }}>
                                                Chapter {book.chapter_id} • {subjectMap[String(book.subject_id)] || `Subject ${book.subject_id}`}
                                            </div>
                                        </div>
                                        <span style={{
                                            padding: '4px 10px', borderRadius: 20, fontSize: '0.65rem',
                                            fontWeight: 700, background: sc.bg, color: sc.color,
                                            border: `1px solid ${sc.border}`, textTransform: 'uppercase'
                                        }}>
                                            {subjectMap[String(book.subject_id)] || 'Other'}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            <style jsx>{`
                @keyframes spin { to { transform: rotate(360deg); } }
            `}</style>
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';

export default function OpsControlRoom() {
    const [ops, setOps] = useState(null);
    const [loading, setLoading] = useState(true);
    const [lastRefresh, setLastRefresh] = useState(null);

    const fetchOps = async () => {
