                                    <div style={{ height: '100%', width: `${pct}%`, background: tier.color, borderRadius: 4, transition: 'width 0.5s ease' }}></div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

'use client';
