                                })()}
                            </>
                        )}
                    </div>

                    {/* Step 2: Capture OMR Sheet */}
                    <div>
                        <label style={{ display: 'block', fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '12px' }}>
                            2. Capture OMR Sheet
                        </label>

                        {/* Dual Capture Buttons */}
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '16px' }}>
                            {/* Camera Button */}
                            <button
                                onClick={() => cameraInputRef.current?.click()}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: '8px',
                                    padding: '20px 12px',
                                    minHeight: '100px',
                                    background: 'linear-gradient(135deg, rgba(99,102,241,0.1), rgba(139,92,246,0.1))',
                                    border: '2px solid rgba(99,102,241,0.3)',
                                    borderRadius: 'var(--radius-lg)',
                                    cursor: 'pointer',
                                    color: 'var(--text-primary)',
                                    fontFamily: 'inherit',
                                    transition: 'border-color var(--transition-fast), background var(--transition-fast)',
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.borderColor = 'var(--accent-primary)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.borderColor = 'rgba(99,102,241,0.3)'; }}
                            >
                                <span style={{ fontSize: '2rem' }}>📷</span>
                                <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>Take Photo</span>
                                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Open camera</span>
                            </button>

                            {/* Gallery/PDF Button */}
                            <button
                                onClick={() => galleryInputRef.current?.click()}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: '8px',
                                    padding: '20px 12px',
                                    minHeight: '100px',
                                    background: 'var(--bg-glass)',
                                    border: '2px solid var(--border-color)',
                                    borderRadius: 'var(--radius-lg)',
                                    cursor: 'pointer',
                                    color: 'var(--text-primary)',
                                    fontFamily: 'inherit',
                                    transition: 'border-color var(--transition-fast), background var(--transition-fast)',
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.borderColor = 'var(--border-glow)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.borderColor = 'var(--border-color)'; }}
                            >
                                <span style={{ fontSize: '2rem' }}>🖼️</span>
                                <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>Upload from Gallery</span>
                                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Photo or PDF</span>
                            </button>
                        </div>

                        {/* Hidden File Inputs */}
                        <input
                            ref={cameraInputRef}
                            type="file"
                            accept="image/*"
                            capture="environment"
                            onChange={handleFileSelect}
                            style={{ display: 'none' }}
                        />
                        <input
                            ref={galleryInputRef}
                            type="file"
                            accept="image/jpeg,image/png,image/webp,image/heic,image/heif,application/pdf"
                            onChange={handleFileSelect}
                            style={{ display: 'none' }}
                        />

                        {/* Image Preview */}
                        {imagePreview && (
                            <Card style={{ padding: '0', overflow: 'hidden', position: 'relative', marginBottom: '8px' }}>
                                {fileInfo?.isPdf ? (
                                    <div style={{
                                        padding: '32px',
                                        textAlign: 'center',
                                        background: 'var(--bg-glass)',
                                    }}>
                                        <span style={{ fontSize: '3rem', display: 'block', marginBottom: '8px' }}>📄</span>
                                        <span style={{ fontWeight: 700, color: 'var(--text-primary)' }}>PDF Uploaded</span>
                                        <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginTop: '4px' }}>{fileInfo.sizeLabel}</div>
                                    </div>
                                ) : (
                                    <div style={{ position: 'relative' }}>
                                        <img
                                            src={imagePreview}
                                            alt="OMR Sheet Preview"
                                            style={{
                                                width: '100%',
                                                maxHeight: '300px',
                                                objectFit: 'contain',
                                                display: 'block',
                                                background: '#000',
                                            }}
                                        />
                                        {fileInfo?.sizeLabel && (
                                            <div style={{
                                                position: 'absolute',
                                                bottom: '8px',
                                                right: '8px',
                                                background: 'rgba(0,0,0,0.7)',
                                                color: 'white',
                                                padding: '4px 8px',
                                                borderRadius: 'var(--radius-sm)',
                                                fontSize: '0.7rem',
                                                fontWeight: 600,
                                            }}>
                                                {fileInfo.sizeLabel}
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* Re-capture button */}
                                <button
                                    onClick={resetScanner}
                                    style={{
                                        position: 'absolute',
                                        top: '8px',
                                        right: '8px',
                                        background: 'rgba(0,0,0,0.6)',
                                        border: 'none',
                                        borderRadius: '50%',
                                        width: '32px',
                                        height: '32px',
                                        color: 'white',
                                        cursor: 'pointer',
                                        fontSize: '1rem',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                    }}
                                    title="Remove and re-capture"
                                >
                                    ✕
                                </button>
                            </Card>
                        )}

                        {/* Dimension Warning */}
                        {fileInfo?.warning && (
                            <div style={{
                                background: 'rgba(245, 158, 11, 0.1)',
                                border: '1px solid rgba(245, 158, 11, 0.3)',
                                color: 'var(--warning)',
                                padding: '12px',
                                borderRadius: 'var(--radius-md)',
                                fontSize: '0.85rem',
                                display: 'flex',
                                gap: '8px',
                                alignItems: 'center',
                            }}>
                                <span>⚠️</span> {fileInfo.warning}
                            </div>
                        )}
                    </div>

                    {/* Step 3: Extract */}
                    <Button
                        variant="primary"
                        size="lg"
                        onClick={handleVisionScan}
                        disabled={!imagePreview || isScanning || !selectedTestId}
                        className="critical-flow"
                        style={{ width: '100%', padding: '16px', fontSize: '1.1rem', minHeight: '56px' }}
                    >
                        {isScanning ? (
                            <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px' }}>
                                <div className="spinner" style={{ width: '20px', height: '20px' }} />
                                Analyzing OMR Sheet…
                            </span>
                        ) : 'Extract Answers'}
                    </Button>
                </div>
            )}
        </div>
    );
}

'use client';
