'use client';
import { useState, useEffect } from 'react';

/**
 * Offline Banner — shows a non-intrusive indicator when network is lost.
 * Auto-hides when connectivity is restored.
 * Also shows a brief "Back online" confirmation.
 */
export default function OfflineBanner() {
    const [isOffline, setIsOffline] = useState(false);
    const [wasOffline, setWasOffline] = useState(false);

    useEffect(() => {
        const goOffline = () => { setIsOffline(true); setWasOffline(true); };
        const goOnline = () => {
            setIsOffline(false);
            // Show "back online" for 3 seconds
            setTimeout(() => setWasOffline(false), 3000);
        };

        // Check initial state
        if (typeof navigator !== 'undefined' && !navigator.onLine) {
            setIsOffline(true);
            setWasOffline(true);
        }

        window.addEventListener('online', goOnline);
        window.addEventListener('offline', goOffline);

        return () => {
            window.removeEventListener('online', goOnline);
            window.removeEventListener('offline', goOffline);
        };
    }, []);

    if (!isOffline && !wasOffline) return null;

    return (
        <div
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                zIndex: 'var(--z-critical)',
                padding: '10px 16px',
                textAlign: 'center',
                fontSize: '0.85rem',
                fontWeight: 600,
                transition: 'all 0.3s ease',
                background: isOffline
                    ? 'linear-gradient(90deg, #dc2626, #b91c1c)'
                    : 'linear-gradient(90deg, #16a34a, #15803d)',
                color: '#fff',
                boxShadow: '0 2px 8px rgba(0,0,0,0.3)',
            }}
        >
            {isOffline ? (
                <>📡 You&apos;re offline — your progress is saved locally and will sync when you reconnect</>
            ) : (
                <>✅ Back online — syncing your data</>
            )}
        </div>
    );
}

'use client';
import { useState, useEffect, useRef } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import ReactMarkdown from 'react-markdown';
import { TrustBadge } from '@/components/trust/TrustBadge';
import 'react-pdf/dist/Page/AnnotationLayer.css';
import 'react-pdf/dist/Page/TextLayer.css';

// Set worker source
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

export default function PDFViewerClient({ book }) {
    const [numPages, setNumPages] = useState(null);
    const [pageNumber, setPageNumber] = useState(1);
    const [selection, setSelection] = useState(null);
    const [explanation, setExplanation] = useState(null);
    const [loadingAI, setLoadingAI] = useState(false);

    const [zoom, setZoom] = useState(1.2);

    const containerRef = useRef(null);

    function onDocumentLoadSuccess({ numPages }) {
        setNumPages(numPages);
    }

    const handleTextSelection = () => {
        const sel = window.getSelection();
        const text = sel.toString().trim();

        if (text.length > 5) {
            const range = sel.getRangeAt(0);
            const rect = range.getBoundingClientRect();

            setSelection({
                text,
                top: rect.top + window.scrollY - 40,
                left: rect.left + window.scrollX,
            });
        } else {
            setSelection(null);
        }
    };

    const handleExplain = async () => {
        if (!selection) return;
        setLoadingAI(true);
        setExplanation(null);

        try {
            const res = await fetch('/api/ncert/explain', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ text: selection.text, bookId: book.id })
            });
            const data = await res.json();
            setExplanation(data.explanation);
        } catch (err) {
            console.error(err);
            setExplanation('Failed to get explanation.');
        } finally {
            setLoadingAI(false);
        }
    };

    const zoomIn = () => setZoom(z => Math.min(z + 0.2, 3.0));
    const zoomOut = () => setZoom(z => Math.max(z - 0.2, 0.5));

    return (
        <div className="flex gap-4 h-full bg-gray-900" onMouseUp={handleTextSelection}>
            {/* Sidebar: Notes/Highlights */}
            <div className="w-1/4 card h-full scrollable hidden lg:block bg-gray-950 border-r border-gray-800 rounded-none">
                <h3 className="text-xl font-bold text-white mb-2">Highlights</h3>
                <p className="text-gray-400 text-sm">Select text in the PDF to explain concepts with AI.</p>
                {/* Placeholder for saved highlights */}
                <div className="mt-8 p-4 bg-gray-900 rounded-lg border border-gray-800">
                    <div className="text-center text-gray-500 text-sm">
                        No highlights saved yet.
                    </div>
                </div>
            </div>

            {/* Main Viewer */}
            <div className="flex-1 h-full overflow-auto relative flex flex-col items-center bg-gray-800 p-4" ref={containerRef}>

                {/* Top Controls Toolbar */}
                <div className="sticky top-0 z-40 bg-gray-900/90 backdrop-blur border border-gray-700 p-3 rounded-xl shadow-lg flex gap-6 items-center mb-6 w-full max-w-4xl justify-between">
                    <div className="flex items-center gap-2">
                        <span className="text-white font-medium text-sm">
                            {numPages ? `${numPages} Pages` : 'Loading...'}
                        </span>
                    </div>

                    <div className="flex items-center gap-2">
                        <button onClick={zoomOut} aria-label="Zoom Out" className="w-11 h-11 flex items-center justify-center rounded-lg bg-gray-800 text-white hover:bg-gray-700" title="Zoom Out">
                            -
                        </button>
                        <span className="text-gray-300 text-sm w-12 text-center">{Math.round(zoom * 100)}%</span>
                        <button onClick={zoomIn} aria-label="Zoom In" className="w-11 h-11 flex items-center justify-center rounded-lg bg-gray-800 text-white hover:bg-gray-700" title="Zoom In">
                            +
                        </button>
                    </div>
                </div>

                <div className="mb-20 w-full flex flex-col items-center" style={{ minHeight: 800 }}>
                    <Document
                        file={book.file_path}
                        onLoadSuccess={onDocumentLoadSuccess}
                        className="pdf-document flex flex-col gap-6"
                        loading={<div className="p-20 text-center text-gray-400 font-bold">Loading PDF...</div>}
                    >
                        {Array.from(new Array(numPages || 0), (el, index) => (
                            <div key={`page_${index + 1}`} className="shadow-2xl bg-white rounded-lg overflow-hidden">
                                <Page
                                    pageNumber={index + 1}
                                    scale={zoom}
                                    renderTextLayer={true}
                                    renderAnnotationLayer={true}
                                    className="bg-white"
                                />
                            </div>
                        ))}
                    </Document>
                </div>

                {/* Text Selection Popup */}
                {selection && !explanation && (
                    <div
                        className="absolute z-50 bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-lg shadow-xl cursor-pointer flex items-center gap-2 transform -translate-x-1/2 transition-colors border border-blue-400 font-bold"
                        style={{ top: selection.top, left: selection.left + 50 }}
                        onClick={handleExplain}
                        onMouseDown={(e) => e.stopPropagation()}
                    >
                        ✨ Explain with AI
                    </div>
                )}

                {/* AI Explanation Modal */}
                {(loadingAI || explanation) && (
                    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4" onClick={() => setExplanation(null)}>
                        <div className="bg-gray-900 border border-gray-700 shadow-2xl p-6 rounded-2xl max-w-lg w-full text-white m-4" onClick={e => e.stopPropagation()}>
                            <div className="flex justify-between items-center mb-4 pb-4 border-b border-gray-800">
                                <div className="flex items-center gap-3">
                                    <h3 className="text-xl font-bold flex items-center gap-2 m-0">✨ AI Explanation</h3>
                                    {!loadingAI && <TrustBadge type="ai-confidence" meta={{ score: 0.95 }} />}
                                </div>
                                <button onClick={() => setExplanation(null)} aria-label="Close explanation" className="w-11 h-11 flex items-center justify-center text-gray-400 hover:text-white text-2xl" style={{ margin: '-12px -12px 0 0' }}>×</button>
                            </div>

                            {loadingAI ? (
                                <div className="py-10 text-center">
                                    <div className="spinner mx-auto mb-4 border-blue-500"></div>
                                    <p className="text-gray-400">Analyzing NCERT concept...</p>
                                </div>
                            ) : (
                                <div>
                                    <div className="mb-6 p-4 bg-gray-950 border border-gray-800 rounded-xl relative overflow-hidden">
                                        <div className="absolute top-0 left-0 w-1 h-full bg-blue-500"></div>
                                        <p className="text-sm text-gray-300 italic">"{selection?.text}"</p>
                                    </div>
                                    <div className="prose prose-invert max-w-none text-gray-200">
                                        <ReactMarkdown>{explanation}</ReactMarkdown>
                                    </div>
                                    <button className="btn btn-primary w-full mt-6 py-3 font-bold text-lg rounded-xl" onClick={() => setExplanation(null)}>
                                        Got it!
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";
import { useState, useEffect } from 'react';

export default function ParentSettings() {
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [message, setMessage] = useState('');
    const [consentGiven, setConsentGiven] = useState(false);

    useEffect(() => {
        fetch('/api/user/parent-settings')
            .then(res => res.json())
            .then(data => {
                if (data.parent_email) setEmail(data.parent_email);
                if (data.parent_phone) setPhone(data.parent_phone);
                if (data.parent_consent_given_at) setConsentGiven(true);
                setLoading(false);
            })
            .catch(err => {
                console.error("Failed to load settings", err);
                setLoading(false);
            });
    }, []);

    const handleSave = async (e) => {
        e.preventDefault();
        if (!consentGiven) {
            setMessage('❌ You must provide consent to share your reports.');
            return;
        }
        setSaving(true);
        setMessage('');

        try {
            const res = await fetch('/api/user/parent-settings', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ parent_email: email, parent_phone: phone, consent_given: consentGiven })
            });
            const data = await res.json();

            if (res.ok) {
                setMessage('✅ Settings saved successfully!');
            } else {
                setMessage('❌ ' + (data.error || 'Failed to save'));
            }
        } catch (err) {
            setMessage('❌ Network Error');
        } finally {
            setSaving(false);
        }
    };

    if (loading) return (
        <div className="card animate-pulse" style={{ height: '120px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div className="spinner" style={{ width: 30, height: 30 }}></div>
        </div>
    );

    return (
        <div className="card">
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                <h3 style={{ fontSize: '1.4rem', margin: 0 }}>👨‍👩‍👧‍👦 Parent Connect</h3>
                <span className="badge badge-warning" style={{ fontSize: '0.75rem', padding: '4px 8px' }}>Early Access Beta</span>
            </div>
            <p className="text-muted text-sm mb-6" style={{ lineHeight: 1.6 }}>
                Add your parent's details to send them <strong style={{ color: 'var(--text-primary)' }}>Weekly Progress Reports</strong>.
                This helps keep them informed about your hard work and improvements.
            </p>

            <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                <div>
                    <label style={{ display: 'block', marginBottom: '8px', fontSize: '0.9rem', color: 'var(--text-muted)' }}>Parent's Email</label>
                    <input
                        type="email"
                        value={email}
                        onChange={e => setEmail(e.target.value)}
                        placeholder="parent@example.com"
                        className="input"
                    />
                </div>

                <div>
                    <label style={{ display: 'block', marginBottom: '8px', fontSize: '0.9rem', color: 'var(--text-muted)' }}>Parent's Phone (Optional)</label>
                    <input
                        type="tel"
                        value={phone}
                        onChange={e => setPhone(e.target.value)}
                        placeholder="+91 9876543210"
                        className="input"
                    />
                </div>

                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px', marginTop: '10px', padding: '12px', background: 'var(--bg-glass)', borderRadius: '8px', border: '1px solid var(--border)' }}>
                    <input 
                        type="checkbox" 
                        id="parentConsent" 
                        checked={consentGiven}
                        onChange={e => setConsentGiven(e.target.checked)}
                        style={{ marginTop: '4px', cursor: 'pointer' }}
                    />
                    <label htmlFor="parentConsent" style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', lineHeight: 1.5, cursor: 'pointer' }}>
                        I consent to sharing my weekly academic performance, test scores, and weak topic analysis with the parent email/phone provided above. I understand I can revoke this at any time by clearing my details.
                    </label>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '10px' }}>
                    <span style={{ fontSize: '0.9rem', fontWeight: 600, color: message.includes('❌') ? 'var(--danger)' : 'var(--success)' }}>
                        {message}
                    </span>
                    <button
                        type="submit"
                        disabled={saving}
                        className="btn btn-primary"
                        style={{ minWidth: '160px' }}
                    >
                        {saving ? 'Saving...' : 'Save Settings'}
                    </button>
                </div>
            </form>
        </div>
    );
}

